 2. Frontend (React + Tailwind CSS, PWA, Glassmorphism, Pink gradiens)

project/frontend/src/App.jsx
jsx
import React, { useState } from "react";

export default function App() {
  const [file, setFile] = useState();
  const [result, setResult] = useState(null);
  const [loading, setLoading] = useState(false);

  const handleFile = (e) => setFile(e.target.files[0]);

  const handleUpload = async () => {
    if (!file) return;
    setLoading(true);
    let formData = new FormData();
    formData.append("file", file);
    const res = await fetch("http://localhost:8000/upscale/", {
      method: "POST",
      body: formData,
    });
    const json = await res.json();
    setResult(json.output_image_path);
    setLoading(false);
  };

  return (
    <div className="relative w-screen h-screen bg-gradient-to-br from-black via-fuchsia-900 to-pink-600 flex items-center justify-center overflow-hidden">
      <AnimatedGlassBG />
      <div className="z-20 backdrop-blur-lg bg-[rgba(30,23,40,0.35)] border border-pink-300/20 shadow-lg rounded-3xl p-8 max-w-sm w-full flex flex-col items-center"
           style={{
             WebkitBackdropFilter: "blur(24px)",
             background: "linear-gradient(120deg,rgba(255,0,128,0.07),rgba(255,38,125,0.04),rgba(0,0,0,0.35))",
             boxShadow: "0 8px 50px 4px rgba(212,58,130,0.09)"
          }}>
        <div className="text-3xl font-bold text-pink-300 mb-2" style={{fontFamily: "San Francisco, Arial, sans-serif"}}>UltraBlend SR</div>
        <div className="text-pink-200/80 text-base mb-6 text-center">
          5-lépcsős szuperrezolúciós AI pipeline<br/>PWA, glassmorphism, iOS-ra optimalizálva
        </div>
        <input type="file" className="hidden" id="fileinput" onChange={handleFile} />
        <label htmlFor="fileinput"
          className="px-6 py-2 cursor-pointer mb-4 rounded-xl bg-pink-500/60 hover:bg-pink-600/70 text-white font-semibold shadow-glass transition"
        >
          Kép kiválasztása
        </label>
        <button type="button" onClick={handleUpload}
                className="px-6 py-2 bg-gradient-to-r from-fuchsia-500 via-pink-600 to-fuchsia-400 rounded-xl font-bold text-lg text-white shadow-lg mb-4 hover:scale-105 transition disabled:opacity-60"
                disabled={!file || loading}>
          {loading ? "Felskálázás zajlik..." : "Blending & Upscale"}
        </button>
        {result && <img src={result} alt="output" className="mt-6 rounded-lg shadow-glass" width={320}/>}
      </div>
    </div>
  );
}

function AnimatedGlassBG() {
  return (
    <div className="absolute inset-0 z-10 animate-slow-move pointer-events-none"
      style={{
        background:
          "radial-gradient(ellipse 180% 80% at 10% 20%, rgba(254,58,158,0.13) 0%, transparent 70%)," +
          "radial-gradient(ellipse 65% 80% at 98% 89%, rgba(219,0,255,0.14) 2%, transparent 77%)," +
          "radial-gradient(circle at 50% 55%, rgba(180,10,100,0.17) 0px, transparent 66%)",
        filter: "blur(60px)",
        opacity: 0.7,
        transition: "background 2s linear"
      }}
    />
  );
}


